import React from "react";
import { MessageCircle, Instagram } from "lucide-react";

export default function FloatingButtons() {
  const whatsappLinks = [
    { number: "919888919983", label: "Chat with us" },
    { number: "917355555649", label: "Alternative contact" },
  ];

  return (
    <div className="fixed bottom-6 right-6 z-50 flex flex-col gap-3">
      {whatsappLinks.map((wa, index) => (
        <a key={wa.number} href={`https://wa.me/${wa.number}?text=Hi!%20I'm%20interested%20in%20D%20SAJAWAT%20fabrics%20for%20wedding/event`} target="_blank" rel="noopener noreferrer" className="relative group" title={wa.label}>
          <div className="absolute inset-0 rounded-full pulse-ring" />
          <div className="float-btn float-wa relative" style={{ width: 56, height: 56 }}><MessageCircle size={26} strokeWidth={1.5} color="white" /></div>
          <div className="absolute right-full mr-3 top-1/2 -translate-y-1/2 px-3 py-2 rounded-sm text-xs whitespace-nowrap opacity-0 group-hover:opacity-100 transition-opacity duration-300 pointer-events-none" style={{ background: "rgba(26, 8, 10, 0.95)", border: "1px solid rgba(212, 175, 55, 0.4)", color: "#f7e7ce" }}>{wa.label}</div>
        </a>
      ))}

      <a href="https://www.instagram.com/d_sajawat/" target="_blank" rel="noopener noreferrer" className="relative group" title="Follow us on Instagram">
        <div className="float-btn float-ig" style={{ width: 56, height: 56 }}><Instagram size={24} strokeWidth={1.5} color="white" /></div>
        <div className="absolute right-full mr-3 top-1/2 -translate-y-1/2 px-3 py-2 rounded-sm text-xs whitespace-nowrap opacity-0 group-hover:opacity-100 transition-opacity duration-300 pointer-events-none" style={{ background: "rgba(26, 8, 10, 0.95)", border: "1px solid rgba(212, 175, 55, 0.4)", color: "#f7e7ce" }}>@d_sajawat</div>
      </a>
    </div>
  );
}
